import{_ as a}from"./chunks/9.8JG1FfiA.js";import{_ as n}from"./chunks/image1.YJCAcCic.js";import{_ as r}from"./chunks/image14.CLKeYbCZ.js";import{_ as s}from"./chunks/image.BikqRkQy.js";import{_ as l,a as t,b as c,c as d}from"./chunks/community.D8XXOc5B.js";import{_ as h}from"./chunks/image1.DiovXIVI.js";import{_ as g}from"./chunks/image6.Cdq5CsCC.js";import{_ as m,C as p,o as u,c as f,aj as o,E as _}from"./chunks/framework.Cwzc8Cgk.js";const w="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1.4QLz5BBW.png",b="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image2.CfcKBSE4.png",v="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image3.C8xoiTSp.png",E=JSON.parse('{"title":"3.9 Face Sensing Windmill","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.9 Face Sensing Windmill.md","filePath":"docs/3. Creative Building & Styling/3.9 Face Sensing Windmill.md"}'),y={name:"docs/3. Creative Building & Styling/3.9 Face Sensing Windmill.md"};function x(k,e,S,P,T,q){const i=p("pdf");return u(),f("div",null,[e[0]||(e[0]=o('<h1 id="_3-9-face-sensing-windmill" tabindex="-1">3.9 Face Sensing Windmill <a class="header-anchor" href="#_3-9-face-sensing-windmill" aria-label="Permalink to &quot;3.9 Face Sensing Windmill&quot;">​</a></h1><h2 id="_3-9-1-lesson-introduction" tabindex="-1">3.9.1 Lesson Introduction <a class="header-anchor" href="#_3-9-1-lesson-introduction" aria-label="Permalink to &quot;3.9.1 Lesson Introduction&quot;">​</a></h2><p>The Face Sensing Windmill is an engaging interactive robotics project built with modular blocks. The front of the support stand features the WonderLens vision module as its visual camera, while the central rotating shaft connects to a 360° block motor to drive the windmill blades. The modular mechanical design ensures straightforward assembly and accessible wiring. When the camera detects a face in the frame, the servo drives the blades to rotate continuously. When the face moves out of camera view, the windmill halts immediately, implementing responsive face-sensing start-stop interaction. This project provides hands-on exploration of AI face detection and servo speed coordination.</p><img loading="lazy" height="1080" width="1080" src="'+a+'" class="common_img" style="width:300px;"><h2 id="_3-9-2-learning-objectives" tabindex="-1">3.9.2 Learning Objectives <a class="header-anchor" href="#_3-9-2-learning-objectives" aria-label="Permalink to &quot;3.9.2 Learning Objectives&quot;">​</a></h2><ol><li>Master face detection using the WonderLens vision module. Learn methods for reading and verifying face position, count, and ID signals.</li><li>Program speed and direction control routines for the 360° block motor, adjusting rotation parameters and motion patterns.</li><li>Master closed-loop control linking face detection states with servo motion, dynamically regulating blade speed based on face counts and IDs.</li><li>Assemble the windmill model and debug the program. Develop foundational skills in creating interactive AI face-activated robotics projects.</li></ol><h2 id="_3-9-3-assembly-guide" tabindex="-1">3.9.3 Assembly Guide <a class="header-anchor" href="#_3-9-3-assembly-guide" aria-label="Permalink to &quot;3.9.3 Assembly Guide&quot;">​</a></h2>',7)),_(i,{src:"../../_static/shared/pdf/chapter_3/9.pdf"}),e[1]||(e[1]=o('<h2 id="_3-9-4-hardware-wiring" tabindex="-1">3.9.4 Hardware Wiring <a class="header-anchor" href="#_3-9-4-hardware-wiring" aria-label="Permalink to &quot;3.9.4 Hardware Wiring&quot;">​</a></h2><p>Connect the WonderLens vision module cable to the <strong>P1</strong> port of the ESP32 controller.</p><p>Connect the 360° block motor cable to the <strong>S1</strong> port of the ESP32 controller, with the servo&#39;s <strong>orange</strong> wire plugged into the <strong>white</strong> pin of S1.</p><p>Wiring diagram:</p><img loading="lazy" height="1220" width="1100" src="'+w+'" class="common_img" style="width:400px;"><h2 id="_3-9-5-programming" tabindex="-1">3.9.5 Programming <a class="header-anchor" href="#_3-9-5-programming" aria-label="Permalink to &quot;3.9.5 Programming&quot;">​</a></h2><h3 id="_1-program-schematic" tabindex="-1">(1) Program Schematic <a class="header-anchor" href="#_1-program-schematic" aria-label="Permalink to &quot;(1) Program Schematic&quot;">​</a></h3><img loading="lazy" height="470" width="370" src="'+b+'" class="common_img" style="width:350px;"><h3 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2) Adding Extensions&quot;">​</a></h3><ul><li>Click the <strong>Extensions</strong> button and select the <strong>WonderLens</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+n+'" class="common_img" style="width:800px;"><h3 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Function Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="108" width="524" src="'+r+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="51" width="75" src="'+s+'" class="common_img"></td><td style="text-align:left;">Controls the servo connected to the specified port to rotate at the set speed.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="412" width="760" src="'+l+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Switches the AI vision operating mode of the vision module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="117" width="432" src="'+c+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Refreshes the camera feed and reads recognition data for the current vision mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="99" width="471" src="'+h+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Detects whether a face appears in the camera frame and returns a Boolean result.</td></tr></tbody></table><h3 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h3><ol><li><p>Initialization: At startup, initialize the WonderLens vision module at port <strong>P1</strong> and switch the operating mode to face recognition.</p></li><li><p>Main Loop: The program continuously updates and retrieves recognition results from the WonderLens vision module, evaluating whether any face is detected. If a face is detected, servo <strong>S1</strong> rotates at a speed of 80. Otherwise, the speed of servo <strong>S1</strong> is set to 0. Each loop iteration pauses for 0.01 s.</p></li></ol><img loading="lazy" height="488" width="454" src="'+v+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1gpd83ho-Cf-T1LV6VETKvwf1mI7A8Bfg?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-9-6-program-upload" tabindex="-1">3.9.6 Program Upload <a class="header-anchor" href="#_3-9-6-program-upload" aria-label="Permalink to &quot;3.9.6 Program Upload&quot;">​</a></h2><img loading="lazy" height="360" width="640" src="'+g+'" class="common_img" style="width:800px;"><h2 id="_3-9-7-expansion-and-challenge" tabindex="-1">3.9.7 Expansion and Challenge <a class="header-anchor" href="#_3-9-7-expansion-and-challenge" aria-label="Permalink to &quot;3.9.7 Expansion and Challenge&quot;">​</a></h2><p><strong>Challenge Task 1: Multi-Face and Recognized ID Tiered Speed Regulation with RGB Lighting</strong></p><ol><li><p>Project Goal: Match distinct windmill rotation speeds and lighting effects based on face count and identity, stopping the windmill when no face is present. Single face: the servo rotates at low speed. Multiple faces: the servo rotates at high speed. Enrolled familiar face ID: the servo rotates at high speed while RGB lights cycle and flash. No face detected: the servo halts and the lights turn off.</p></li><li><p>Implementation Strategy: Retrieve face count and face ID data, define numeric variables to store values, and construct multi-tiered conditional statements. Configure corresponding servo speeds and RGB lighting programs for single, multiple, and familiar face branches, while assigning stop and power-off logic to the empty detection branch.</p></li><li><p>Key Challenges: Maintaining stable face count and ID readings without jitter, switching speeds smoothly without sudden jerking, and synchronizing lighting effects with windmill motion.</p></li></ol><p><strong>Challenge Task 2: Delayed Windmill Deceleration Upon Face Disappearance</strong></p><ol><li><p>Project Goal: When a face moves out of camera view, the windmill does not stop abruptly. It continues spinning at its current speed for 3 s. Once the countdown expires, the servo decelerates to a halt and the lights extinguish.</p></li><li><p>Implementation Strategy: Introduce a timer variable to start a countdown when the face disappears. Maintain blade rotation and lighting while the countdown runs. Stop the servo and turn off the lights once the timer reaches zero.</p></li><li><p>Key Challenges: Running the countdown routine without interrupting continuous camera face detection, ensuring that speed control, lighting, and timer logic operate without conflict.</p></li></ol><p><strong>Challenge Task 3: Creative Applications of Face Detection Beyond the Windmill</strong></p><ol><li><p>Smart Face-Sensing Rotating Display Stand: Retain core face detection routines, drive an exhibition pedestal slowly with a servo, and automatically initiate rotation when a visitor approaches.</p></li><li><p>Face-Activated Ambient Lamp: Omit the servo, pair the system with RGB LED light strips, and automatically switch lighting gradient modes upon detecting individuals.</p></li><li><p>Universal Adaptation Strategy: Keep core face detection routines unchanged and swap out output hardware. By adding corresponding peripheral control blocks under the principle of triggering specific actions upon detecting faces, diverse interactive smart robotics projects can be constructed.</p></li></ol><h2 id="_3-9-8-q-a" tabindex="-1">3.9.8 Q&amp;A <a class="header-anchor" href="#_3-9-8-q-a" aria-label="Permalink to &quot;3.9.8 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: During servo wiring, the orange signal wire must connect to the white pin of port S1. What problems occur if it is wired incorrectly?</strong></p><p><strong>Answer</strong>: The white pin of port <strong>S1</strong> is dedicated to transmitting control signals, which the servo relies on to regulate blade rotation speed and start-stop behavior. If the orange signal wire connects to the power or ground pins, the controller cannot transmit control instructions. Two primary failures occur: either the servo remains completely motionless so the windmill cannot spin, or the servo vibrates and rotates erratically, potentially overheating and causing hardware damage. Furthermore, all program code designed to manage windmill rotation and speed regulation becomes ineffective, preventing face-sensing operation.</p><p><strong>Question 2: The camera recognizes faces normally, but the windmill servo does not rotate at all. What are the most common causes and troubleshooting steps?</strong></p><p><strong>Answer</strong>:</p><ol><li><p>Wiring Fault: The orange signal wire of the servo is not plugged into the white signal pin of port <strong>S1</strong>. Troubleshooting: Disconnect the power, then verify the three-pin sequence against the wiring diagram.</p></li><li><p>Program Fault: The servo rotation and speed control blocks are placed outside the conditional branch that executes when a face is detected. Troubleshooting: Open the program and move the servo speed control and delay blocks inside the branch for successful face recognition.</p></li><li><p>Hardware Damage: The servo is defective or port <strong>S1</strong> of the ESP32 controller is damaged. Troubleshooting: Connect a known working servo to port <strong>S1</strong> for testing. If it still fails to move, connect the servo to an alternative servo port on the controller to isolate the issue.</p></li></ol><h2 id="_3-9-9-technical-support-and-product-discussion" tabindex="-1">3.9.9 Technical Support and Product Discussion <a class="header-anchor" href="#_3-9-9-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.9.9 Technical Support and Product Discussion&quot;">​</a></h2><p>Share project ideas and connect with other makers on the <a href="https://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder community</a>:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+d+'" class="common_img" style="width:800px;"></a>',35))])}const F=m(y,[["render",x]]);export{E as __pageData,F as default};
